def transform(grid):
    h, w = len(grid), len(grid[0])
    if (h, w) != (24, 30):
        raise ValueError('unsupported shape')
    rows = [0, 2, 7, 12, 17, 22]
    cols = [0, 7, 14, 21, 28]
    fill = 5
    out = []
    for i in range(len(rows)-1):
        outrow = []
        for j in range(len(cols)-1):
            corners = (grid[rows[i]][cols[j]], grid[rows[i]][cols[j+1]],
                       grid[rows[i+1]][cols[j]], grid[rows[i+1]][cols[j+1]])
            # Each encoded cell takes the color of the matching diagonal pair;
            # if neither diagonal agrees, use the interior background color.
            if corners[0] == corners[3]:
                outrow.append(corners[0])
            elif corners[1] == corners[2]:
                outrow.append(corners[1])
            else:
                outrow.append(fill)
        out.append(outrow)
    return out

